(() => {
  'use strict';
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const HISTORY_KEY = 'nex-osint-pro.history.v1';
  const HISTORY_LIMIT = 75;
  const SYNC_CONFIG_KEY = 'nex-osint-pro.sync.config.v1';
  const SYNC_TOMBSTONES_KEY = 'nex-osint-pro.sync.tombstones.v1';
  const views = {
    overview:'Genel Bakış', investigate:'Hızlı Araştırma', identity:'Username OSINT', telegram:'Telegram Public',
    network:'IP Intelligence', domain:'Domain / RDAP', dns:'DNS Records', certs:'Certificate Intel',
    urlscan:'URL Scan Archive', github:'GitHub Intelligence', email:'Email / MX', websearch:'Web Research',
    history:'Araştırma Geçmişi', sources:'Kaynaklar / API'
  };
  const icons = {overview:'◈',investigate:'⌕',identity:'◎',telegram:'➤',network:'⌁',domain:'◌',dns:'⌘',certs:'▤',urlscan:'◉',github:'⌘',email:'✉',websearch:'↗',history:'◷',sources:'⊞'};
  const typeKeys = {'General':'overview','Username OSINT':'identity','Maigret scan':'identity','Telegram Public':'telegram','IP Intelligence':'network','Domain / RDAP':'domain','DNS Records':'dns','Certificate Intel':'certs','URL Scan Archive':'urlscan','GitHub Intelligence':'github','Email / MX':'email','Web Research':'websearch','Universal lookup':'investigate'};
  let activeView = 'overview';
  let scanDepth = 'standard';
  let lookupKind = 'domain';
  let history = readHistory();
  let currentRun = null;
  let syncConfig = readSyncConfig();
  let syncTombstones = readSyncTombstones();
  let syncTimer = null;
  let syncInFlight = false;
  let syncAgain = false;
  let commandActive = 0;
  const stack = $('#viewStack');

  function readHistory() {
    try { const data = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]'); return Array.isArray(data) ? data.filter(x => x && x.id != null) : []; }
    catch { return []; }
  }
  function persistHistory(options = {}) {
    try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, HISTORY_LIMIT))); }
    catch { toast('Tarayıcı depolaması dolu. Geçmişi dışa aktar veya temizle.', 'error'); }
    renderMetrics(); renderRecent(); if (activeView === 'history') renderHistory();
    if (!options.skipSync) scheduleSync();
  }
  function escapeHTML(value) {
    return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  }
  function safeUrl(value) {
    try { const url = new URL(String(value)); return ['https:','http:'].includes(url.protocol) ? url.href : ''; }
    catch { return ''; }
  }
  function safeLink(value, label='Open ↗') { const url=safeUrl(value); return url ? `<a class="record-link" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)}</a>` : ''; }
  function formatDate(value) {
    try { return new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)); }
    catch { return String(value || '—'); }
  }
  function toast(message, type='ok') {
    const root=$('#toastStack'); if(!root)return;
    const node=document.createElement('div'); node.className=`toast ${type==='error'?'toast-error':''}`;
    node.innerHTML=`<span class="toast-dot"></span><span>${escapeHTML(message)}</span>`;
    root.append(node); setTimeout(()=>{node.style.opacity='0';node.style.transform='translateY(8px)';setTimeout(()=>node.remove(),260)},3700);
  }
  function apiError(error) {
    if (error?.name === 'AbortError') return 'Sorgu zaman aşımına uğradı. Kaynak yavaş veya erişilemez olabilir.';
    return error?.message || 'Bilinmeyen bir hata oluştu.';
  }
  async function api(path, {timeout=40000, ...options}={}) {
    const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),timeout);
    try {
      const response=await fetch(path,{...options,signal:controller.signal,headers:{'Accept':'application/json',...(options.headers||{})}});
      let payload; try { payload=await response.json(); } catch { const error=new Error(`Sunucu geçerli JSON döndürmedi (HTTP ${response.status}).`);error.status=response.status;throw error; }
      if(!response.ok){const error=new Error(payload?.detail||`HTTP ${response.status}`);error.status=response.status;throw error;}
      return payload;
    } catch(error) {
      if(error instanceof TypeError) throw new Error('Yerel API’ye ulaşılamıyor. README’deki başlatma adımlarını uygula; index.html dosyasını tek başına açmak Python backend’ini başlatmaz.');
      throw error;
    } finally { clearTimeout(timer); }
  }
  function countFindings(data) {
    if (!data || typeof data !== 'object') return 0;
    if (Array.isArray(data.results)) return data.results.length;
    if (Array.isArray(data.records)) return data.records.length;
    if (Array.isArray(data.certificates)) return data.certificates.length;
    if (Array.isArray(data.hostnames)) return data.hostnames.length;
    if (Array.isArray(data.public_posts)) return data.public_posts.length;
    if (Array.isArray(data.found)) return data.found.length;
    if (Array.isArray(data.links)) return data.links.length;
    if (Array.isArray(data.recent_repositories)) return data.recent_repositories.length;
    if (data.bundle && Array.isArray(data.bundle)) return data.bundle.reduce((n,x)=>n+(x.ok?countFindings(x.data):0),0);
    if (data.summary?.found != null) return Number(data.summary.found)||0;
    return Object.keys(data.profile||data.rdap||data).filter(k=>!['ok','queried_at','source','source_url','note','limits','raw_url'].includes(k)).length;
  }
  function saveHistory(type,target,payload,summary='') {
    const rec={id:(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`),type,typeKey:typeKeys[type]||'overview',target,time:new Date().toISOString(),summary,source:payload?.source||'Public source',findings:countFindings(payload),result:payload};
    history.unshift(rec);history=history.slice(0,HISTORY_LIMIT);persistHistory();return rec;
  }
  function renderMetrics() {
    const q=$('#metricQueries'), f=$('#metricFindings'); if(q)q.textContent=history.length;
    if(f)f.textContent=history.reduce((sum,rec)=>sum+(Number(rec.findings)||0),0);
  }
  function renderRecent() {
    const el=$('#recentActivity');if(!el)return;
    if(!history.length){el.innerHTML='<div class="empty-state"><span>◷</span><b>Henüz araştırma yok</b><p>İlk sorgunu çalıştırdığında burası gerçek sonuçlarla dolacak.</p><button class="btn btn-glass" data-view="investigate">Araştırmayı başlat</button></div>';return;}
    el.innerHTML=history.slice(0,5).map((rec,i)=>`<div class="history-row"><span class="history-symbol">${icons[rec.typeKey]||'◈'}</span><div class="history-text"><b>${escapeHTML(rec.target)}</b><p>${escapeHTML(rec.type)} · ${escapeHTML(rec.summary||`${rec.findings||0} kayıt`)} · ${formatDate(rec.time)}</p></div><div class="history-actions"><small>${String(i+1).padStart(2,'0')} / ${rec.findings||0} items</small><button class="icon-btn" data-history-open="${escapeHTML(rec.id)}" title="Kaydı aç">↗</button></div></div>`).join('');
  }
  function renderHistory() {
    const el=$('#historyOutput');if(!el)return;
    if(!history.length){el.innerHTML='<div class="empty-state"><span>◷</span><b>No saved evidence</b><p>Çalıştırılan sorgular bu alanda listelenir.</p></div>';return;}
    el.innerHTML=history.map(rec=>`<div class="history-row"><span class="history-symbol">${icons[rec.typeKey]||'◈'}</span><div class="history-text"><b>${escapeHTML(rec.target)}</b><p>${escapeHTML(rec.type)} · ${escapeHTML(rec.summary||`${rec.findings||0} kayıt`)} · ${formatDate(rec.time)} · ${escapeHTML(rec.source||'')}</p></div><div class="history-actions"><small>${rec.findings||0} findings</small><button class="icon-btn" data-history-open="${escapeHTML(rec.id)}" title="Kaydı görüntüle">↗</button><button class="icon-btn" data-history-delete="${escapeHTML(rec.id)}" title="Kaydı sil">×</button></div></div>`).join('');
  }
  function closeSidebar(){ $('#sidebar')?.classList.remove('mobile-open'); $('#menuScrim')?.classList.remove('visible'); }
  function openSidebar(){ $('#sidebar')?.classList.add('mobile-open'); $('#menuScrim')?.classList.add('visible'); }
  function navigate(view) {
    if(!views[view])return;
    if(view===activeView){closeSidebar();return;}
    const old=$(`#view-${activeView}`),next=$(`#view-${view}`);if(!next)return;
    const change=()=>{if(old){old.classList.remove('active');old.classList.add('leaving');setTimeout(()=>old.classList.remove('leaving'),280);}next.classList.remove('leaving');next.classList.add('active');activeView=view;$('#crumb').textContent=views[view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='history')renderHistory();if(view==='overview'){renderRecent();renderMetrics();}closeSidebar();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
    if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){try{document.startViewTransition(change);}catch{change();}}else change();
  }
  function loadingHTML(title,detail='Gerçek kaynaktan veri yanıtı bekleniyor…'){return `<div class="loading-state"><span class="spin"></span><b>${escapeHTML(title)}</b><p>${escapeHTML(detail)}</p><div class="query-progress" style="width:min(240px,80%)"><i></i></div></div>`;}
  function errorHTML(message,source=''){const link=safeUrl(source);return `<div class="result-placeholder error-placeholder"><span class="placeholder-symbol">!</span><b>Canlı sorgu tamamlanamadı</b><p>${escapeHTML(message)}</p>${link?`<a class="source-link" href="${escapeHTML(link)}" target="_blank" rel="noopener noreferrer">Kaynağı doğrudan aç ↗</a>`:''}</div>`;}
  function dataCell(label,value,sub='') {const shown=value===null||value===undefined||value===''?'Not published':value;return `<div class="data-cell"><label>${escapeHTML(label)}</label><strong>${escapeHTML(shown)}</strong>${sub?`<small>${escapeHTML(sub)}</small>`:''}</div>`;}
  function recordRow(title,value,type='',href='') {return `<div class="record-row"><div class="record-main"><b>${escapeHTML(title)}</b><p>${escapeHTML(value)}</p></div><div class="record-meta">${type?`<span class="record-chip">${escapeHTML(type)}</span>`:''}${safeLink(href)}</div></div>`;}
  function panelHTML(title,subtitle,body,extra=''){return `<article class="panel glass-edge"><div class="panel-head"><div><span class="panel-overline">${escapeHTML(subtitle||'LIVE QUERY')}</span><h3>${escapeHTML(title)}</h3></div>${extra}</div>${body}</article>`;}
  function setStatus(selector,label,state='idle'){const el=$(selector);if(el){el.textContent=label;el.className=`result-state state-${state}`;}}
  function formBusy(form,busy,label='Query running…'){const btn=$('button[type="submit"]',form);if(!btn)return;if(busy){if(!btn.dataset.original)btn.dataset.original=btn.innerHTML;btn.disabled=true;btn.innerHTML=`<span class="spin" style="width:13px;height:13px"></span> ${escapeHTML(label)}`;}else{btn.disabled=false;if(btn.dataset.original){btn.innerHTML=btn.dataset.original;delete btn.dataset.original;}}}
  async function runForm(form,output,title,fn,options={}){
    if(currentRun)currentRun.abort();currentRun=new AbortController();
    output.innerHTML=loadingHTML(options.loading||'Live query running',options.detail||'Gerçek veri kaynağından yanıt bekleniyor.');formBusy(form,true,options.button||'Querying');if(options.status)setStatus(options.status,'RUNNING','running');
    try{const payload=await fn();output.innerHTML=options.render?options.render(payload):renderGeneric(payload);if(options.status)setStatus(options.status,'LIVE DATA','success');saveHistory(title,options.target||'',payload,options.summary||`${countFindings(payload)} kayıt döndü`);toast(`${title}: canlı yanıt alındı.`);return payload;}
    catch(error){output.innerHTML=errorHTML(apiError(error),options.source||'');if(options.status)setStatus(options.status,'ERROR','error');toast(apiError(error),'error');return null;}
    finally{formBusy(form,false);currentRun=null;}
  }
  function renderGeneric(data){
    const omit=new Set(['ok','queried_at','source','source_url','note','limits','raw_url','partial_errors']);const simple=[];
    for(const [key,value] of Object.entries(data||{})){if(omit.has(key)||value==null||typeof value==='object')continue;simple.push(dataCell(key.replaceAll('_',' '),value));}
    const arrays=[];for(const [key,value] of Object.entries(data||{})){if(omit.has(key)||!Array.isArray(value)||!value.length)continue;arrays.push(`<div class="section-subtitle">${escapeHTML(key.replaceAll('_',' '))} <span class="muted">(${value.length})</span></div><div class="record-list">${value.slice(0,100).map((item,i)=>recordRow(item?.name||item?.site||item?.type||`${key} ${i+1}`,typeof item==='object'?JSON.stringify(item):item,'',item?.url||item?.source_url||'')).join('')}</div>`);}
    return `<div class="result-grid-output">${simple.length?`<div class="data-grid">${simple.join('')}</div>`:''}${arrays.join('')}${data?.source?`<div class="source-attribution">SOURCE / ${safeLink(data.source_url,data.source+' ↗')}<span>${formatDate(data.queried_at||new Date())}</span></div>`:''}${data?.note?`<p class="output-note">ⓘ ${escapeHTML(data.note)}</p>`:''}</div>`;
  }
  function renderIp(data){const coords=data.latitude!=null&&data.longitude!=null?`${data.latitude}, ${data.longitude}`:null;const cells=[dataCell('IP ADDRESS',data.ip,data.type),dataCell('COUNTRY',`${data.flag||''} ${data.country||''}`,data.country_code),dataCell('CITY / REGION',[data.city,data.region].filter(Boolean).join(', ')),dataCell('ISP',data.isp),dataCell('ORGANIZATION',data.org),dataCell('ASN',data.asn),dataCell('TIMEZONE',data.timezone,data.utc_offset),dataCell('POSTAL',data.postal),dataCell('COORDINATES',coords,'Approximate IP geolocation')];return panelHTML('Network attribution','IPWHO.IS LIVE RESPONSE',`<div class="data-grid">${cells.join('')}</div><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'ipwho.is ↗')}<span>${formatDate(data.queried_at)}</span></div><p class="output-note">ⓘ ${escapeHTML(data.accuracy_note||'IP location is approximate network metadata.')}</p>`);}
  function renderDns(data){const groups={};(data.records||[]).forEach(record=>(groups[record.type]||=[]).push(record));const preferred=['A','AAAA','MX','NS','CNAME','SOA','CAA','TXT'];const body=preferred.map(type=>{const records=groups[type]||[];return `<div class="section-subtitle">${type} <span class="muted">(${records.length})</span></div>${records.length?`<div class="record-list">${records.map(r=>recordRow(r.name||data.domain,r.value,type)).join('')}</div>`:`<div class="record-row"><div class="record-main"><b>No record returned</b><p>Kaynak bu kayıt türü için cevap döndürmedi.</p></div><span class="record-chip">${type}</span></div>`}`;}).join('');return `${panelHTML(`DNS records — ${data.domain}`,'CLOUDFLARE DNS OVER HTTPS',body,`<span class="result-state state-success">${(data.records||[]).length} RECORDS</span>`)}${data.partial_errors?.length?`<p class="output-note">Bazı DNS kayıt türleri sorgulanamadı: ${escapeHTML(data.partial_errors.map(x=>x.type).join(', '))}</p>`:''}<div class="source-attribution">SOURCE / ${safeLink(data.source_url,'Cloudflare DNS DoH ↗')}<span>${formatDate(data.queried_at)}</span></div>`;}
  function renderRdap(data){const d=data.rdap||{};const status=(d.status||[]).map(x=>`<span class="pill">${escapeHTML(x)}</span>`).join(' ')||'<span class="subtle">No public status values</span>';const events=(d.events||[]).map(x=>recordRow(x.type||'Event',x.date||'Not published','RDAP')).join('')||'<p class="subtle">No public registration events were returned.</p>';const ns=(d.nameservers||[]).map(x=>recordRow(x,x,'NS')).join('')||'<p class="subtle">No nameserver records returned.</p>';const entities=(d.entities||[]).map(x=>recordRow((x.roles||[]).join(', ')||'Entity',x.name||'Redacted / not provided','ENTITY')).join('')||'<p class="subtle">No registrant entity data published.</p>';const body=`<div class="data-grid">${dataCell('OBJECT TYPE',d.objectClassName)}${dataCell('HANDLE',d.handle)}${dataCell('DOMAIN / NAME',d.ldhName||d.name||data.query)}${dataCell('COUNTRY',d.country)}${dataCell('RDAP SERVER',d.port43)}${dataCell('STATUS COUNT',(d.status||[]).length)}</div><div class="section-subtitle">Published status</div><div class="pill-row">${status}</div><div class="section-subtitle">Registration events</div><div class="record-list">${events}</div><div class="section-subtitle">Nameservers</div><div class="record-list">${ns}</div><div class="section-subtitle">Public registry entities</div><div class="record-list">${entities}</div><p class="output-note">RDAP availability and registrant fields depend on the registry. Privacy-redacted data cannot be recovered by this tool.</p><div class="source-attribution">SOURCE / ${safeLink(data.raw_url||data.source_url,'RDAP endpoint ↗')}<span>${formatDate(data.queried_at)}</span></div>`;return panelHTML(`RDAP — ${data.query||'Target'}`,'REGISTRY / REGISTRAR DATA',body);}
  function renderCerts(data){const hosts=data.hostnames||[];const certs=data.certificates||[];const hostBody=hosts.length?`<div class="record-list">${hosts.map(x=>recordRow(x,'Certificate log hostname','HOST',`https://crt.sh/?q=${encodeURIComponent(x)}`)).join('')}</div>`:'<div class="empty-state" style="min-height:100px"><p>Hostname kaydı bulunamadı veya kaynak boş döndü.</p></div>';const certBody=certs.length?`<div class="record-list">${certs.slice(0,60).map(x=>recordRow(x.common_name||x.name_value||`Certificate ${x.id}`,`${x.issuer||'Issuer not published'} · ${x.not_before||'?'} → ${x.not_after||'?'}`,'CT',`https://crt.sh/?id=${encodeURIComponent(x.id||'')}`)).join('')}</div>`:'<p class="subtle">No certificate rows returned.</p>';return `${panelHTML(`Certificate transparency — ${data.domain}`,'CRT.SH PUBLIC CERTIFICATE LOGS',`<div class="result-counts"><div class="count-box"><small>HOSTNAMES</small><b>${hosts.length}</b></div><div class="count-box"><small>CERTIFICATES</small><b>${certs.length}</b></div><div class="count-box"><small>LIVE STATUS</small><b>?</b></div></div><div class="section-subtitle">Observed hostnames</div>${hostBody}<div class="section-subtitle">Recent certificate rows</div>${certBody}<p class="output-note">ⓘ ${escapeHTML(data.note||'Certificate logs are historical, not proof a host is still active.')}</p>`)}<div class="source-attribution">SOURCE / ${safeLink(data.source_url,'crt.sh ↗')}<span>${formatDate(data.queried_at)}</span></div>`;}
  function renderTelegram(data){const p=data.profile||{};const avatar=safeUrl(p.image_url);const avatarHtml=avatar?`<img class="profile-avatar" src="${escapeHTML(avatar)}" alt="Public preview image" referrerpolicy="no-referrer">`:'<div class="profile-avatar" style="display:grid;place-items:center;font-size:22px">➤</div>';const info=`<div class="profile-head">${avatarHtml}<div class="profile-title"><h2>${escapeHTML(p.title||p.username||data.username)}</h2><p>@${escapeHTML(data.username)} · ${escapeHTML(p.page_extra||p.page_title||'Public web preview')}</p></div>${safeLink(p.canonical_url||data.source_url,'Open t.me ↗')}</div><div class="data-grid">${dataCell('USERNAME',data.username)}${dataCell('PAGE TYPE',data.page_kind)}${dataCell('HTTP STATUS',p.http_status)}${dataCell('TITLE',p.title)}${dataCell('PUBLIC POSTS',(data.public_posts||[]).length,'Visible through t.me/s only')}${dataCell('DESCRIPTION',p.description)}</div>`;const posts=data.public_posts||[];const postBody=posts.length?`<div class="record-list">${posts.map((post,i)=>recordRow(`Public post ${i+1} · ${post.date||'date not shown'}`,`${post.text||'[No text shown]'}${post.views?' · Views: '+post.views:''}`,'PUBLIC POST',post.url||'')).join('')}</div>`:'<div class="empty-state" style="min-height:125px"><span>➤</span><b>No public channel posts returned</b><p>Normal user profiles often expose little or no metadata. This is not an error by itself.</p></div>';return `${panelHTML('Public Telegram page','T.ME PUBLIC WEB PREVIEW',info)}${panelHTML('Visible public channel posts','PUBLIC PREVIEW ONLY',postBody)}<p class="output-note">ⓘ ${escapeHTML(data.note||'Private messages, member lists, phone numbers, or hidden profile data are not accessed.')}</p><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'Telegram public page ↗')}<span>${formatDate(data.queried_at)}</span></div>`;}
  function renderGitHub(data){const p=data.profile||{};const avatar=safeUrl(p.avatar_url);const avatarHtml=avatar?`<img class="profile-avatar" src="${escapeHTML(avatar)}" alt="Public avatar" referrerpolicy="no-referrer">`:'<div class="profile-avatar" style="display:grid;place-items:center">⌘</div>';const repositories=data.recent_repositories||[];return `${panelHTML('GitHub public profile','GITHUB REST API',`<div class="profile-head">${avatarHtml}<div class="profile-title"><h2>${escapeHTML(p.name||p.login||data.username)}</h2><p>@${escapeHTML(p.login||data.username)} · ${escapeHTML(p.bio||'No public bio')} ${p.location?'· '+escapeHTML(p.location):''}</p></div>${safeLink(p.html_url,'Open GitHub ↗')}</div><div class="data-grid">${dataCell('PUBLIC REPOSITORIES',p.public_repos)}${dataCell('FOLLOWERS',p.followers)}${dataCell('FOLLOWING',p.following)}${dataCell('PUBLIC GISTS',p.public_gists)}${dataCell('COMPANY',p.company)}${dataCell('WEBSITE',p.blog)}</div><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'GitHub REST API ↗')}<span>${formatDate(data.queried_at)}</span></div>`)}${panelHTML('Recently updated repositories','PUBLIC REPOSITORY DATA',repositories.length?`<div class="record-list">${repositories.map(r=>recordRow(r.name||'Repository',`${r.description||'No description'} · ${r.language||'Language not specified'} · ★ ${r.stargazers_count??0} · Updated ${r.updated_at||'unknown'}`,'REPO',r.html_url)).join('')}</div>`:'<p class="subtle">No public repositories returned.</p>')}`;}
  function renderMaigret(data){const found=data.found||[],uncertain=data.uncertain||[];const foundHtml=found.length?`<div class="record-list">${found.map(x=>recordRow(x.site,`Rank: ${x.rank??'—'} · HTTP: ${x.http_status??'—'} · Status: ${x.status||'FOUND'}`,'FOUND',x.url)).join('')}</div>`:'<div class="empty-state" style="min-height:110px"><b>No confirmed match returned</b><p>Bu username için seçilen sitelerde doğrulanmış bir eşleşme alınmadı. Bu, internette hesabı olmadığı anlamına gelmez.</p></div>';const uncertainHtml=uncertain.length?`<div class="section-subtitle">Uncertain / blocked responses (${uncertain.length})</div><div class="record-list">${uncertain.map(x=>recordRow(x.site,`Status: ${x.status||'UNKNOWN'} · HTTP: ${x.http_status??'—'}`,'UNCERTAIN',x.url)).join('')}</div>`:'';return `${panelHTML(`Maigret report — @${data.username}`,'OPEN-SOURCE USERNAME SCAN',`<div class="result-counts"><div class="count-box"><small>SITES CHECKED</small><b>${data.sites_checked??data.summary?.checked??0}</b></div><div class="count-box"><small>FOUND LEADS</small><b>${found.length}</b></div><div class="count-box"><small>UNCERTAIN</small><b>${uncertain.length}</b></div></div><div class="section-subtitle">Profile matches — manual verification required</div>${foundHtml}${uncertainHtml}<p class="output-note">ⓘ ${escapeHTML(data.note||'Matches are leads; false positives or blocks are possible.')}</p><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'Maigret on GitHub ↗')}<span>${formatDate(data.queried_at)}</span></div>`)}<div class="bundle-note"><b>Scan depth: ${escapeHTML(data.depth||'standard')}</b><span>Requested ${data.sites_requested||'—'} sites · checked ${data.sites_checked||0}</span></div>`;}
  function renderUrlscan(data){const scans=data.results||[];return `${panelHTML(`urlscan archive — ${data.domain}`,'PUBLIC SCAN SEARCH',`<div class="result-counts"><div class="count-box"><small>RESULTS RETURNED</small><b>${scans.length}</b></div><div class="count-box"><small>TOTAL MATCHES</small><b>${data.total??scans.length}</b></div><div class="count-box"><small>ARCHIVE</small><b>PUBLIC</b></div></div>${scans.length?`<div class="record-list">${scans.map(x=>recordRow(x.title||x.domain||x.url||'Public scan',`${x.time||'Time not published'} · ${x.ip||'IP unknown'} · ${x.country||'Country unknown'} · HTTP ${x.status||'—'}`,'SCAN',x.result_url||x.url)).join('')}</div>`:'<div class="empty-state" style="min-height:120px"><b>No public scan results returned</b><p>Arşivde sonuç olmayabilir veya urlscan servisi anonim erişimi sınırlıyor olabilir.</p></div>'}<p class="output-note">ⓘ ${escapeHTML(data.note||'Historical results do not guarantee current site state.')}</p><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'urlscan.io ↗')}<span>${formatDate(data.queried_at)}</span></div>`)}`;}
  function renderSearchLinks(data){const links=data.links||[];return `${panelHTML(`Search set — ${data.query}`,'OPEN WEB RESEARCH',`<div class="record-list">${links.map(x=>recordRow(x.name,x.purpose,'SEARCH',x.url)).join('')}</div><p class="output-note">ⓘ ${escapeHTML(data.note||'These are genuine search links, not scraped results.')}</p>`)}`;}
  function renderEmail(data){const records=data.records||[],mx=records.filter(x=>x.type==='MX'),txt=records.filter(x=>x.type==='TXT'),spf=txt.filter(x=>String(x.value).toLowerCase().includes('v=spf1')),dmarc=txt.filter(x=>String(x.name||'').toLowerCase().startsWith('_dmarc'));return `${panelHTML(`Mail DNS — ${data.domain}`,'DNS-BASED EMAIL ANALYSIS',`<div class="data-grid">${dataCell('MX RECORDS',mx.length)}${dataCell('SPF RECORDS',spf.length,spf.length?'TXT match':'No SPF TXT detected')}${dataCell('DMARC RECORDS',dmarc.length,dmarc.length?'DMARC TXT match':'No DMARC answer detected')}</div><div class="section-subtitle">MX records</div><div class="record-list">${mx.map(x=>recordRow(x.name,x.value,'MX')).join('')||'<p class="subtle">No MX record returned.</p>'}</div><div class="section-subtitle">SPF / DMARC / NS / SOA</div><div class="record-list">${records.filter(x=>['TXT','NS','SOA'].includes(x.type)).map(x=>recordRow(x.name,x.value,x.type)).join('')||'<p class="subtle">No related record returned.</p>'}</div><p class="output-note">This checks public DNS configuration only. It does not verify mailbox existence or password breaches.</p><div class="source-attribution">SOURCE / ${safeLink(data.source_url,'Cloudflare DNS DoH ↗')}</div>`)}`;}
  function renderBundle(data){const rows=data.bundle||[];return `<div class="bundle-note"><b>Multi-source lookup</b><span>${rows.filter(x=>x.ok).length} / ${rows.length} live sources responded</span></div>${rows.map((row,index)=>`<article class="panel glass-edge"><div class="panel-head"><div><span class="panel-overline">SOURCE ${String(index+1).padStart(2,'0')}</span><h3>${escapeHTML(row.label)}</h3></div><span class="result-state ${row.ok?'state-success':'state-error'}">${row.ok?'LIVE DATA':'SOURCE ERROR'}</span></div>${row.ok?renderBundleChild(row.data):errorHTML(row.error,row.source)}</article>`).join('')}<p class="output-note">Only the services that responded are shown as live data. A failed source is not treated as an empty result.</p>`;}
  function renderBundleChild(data){if(data.rdap)return renderRdap(data);if(data.records&&data.record_types)return renderDns(data);if(data.ip&&data.isp!==undefined)return renderIp(data);if(data.certificates)return renderCerts(data);if(data.total!==undefined&&data.results)return renderUrlscan(data);if(data.profile&&data.recent_repositories)return renderGitHub(data);if(data.public_posts||data.page_kind)return renderTelegram(data);if(data.found&&data.summary)return renderMaigret(data);return renderGeneric(data);}
  async function runBundle(target,descriptors){const results=await Promise.all(descriptors.map(async d=>{try{return {label:d.label,ok:true,data:await api(d.path,{timeout:d.timeout||45000})};}catch(e){return {label:d.label,ok:false,error:apiError(e),source:d.source||''};}}));return {ok:true,target,bundle:results,source:'NEX multi-source bundle',source_url:'',queried_at:new Date().toISOString(),note:'Each source is shown independently. Failed source requests are not treated as negative results.'};}

  // Health status: source endpoints are only used after a user submits an actual target.
  async function healthCheck(){const title=$('#universalBackendState');try{const data=await api('/api/health',{timeout:7000});$('#apiState').textContent='Backend connected';$('#apiMeta').textContent=`API ready · ${data.maigret_available?'Maigret ready':'Maigret not installed'}`;$('#metricHealth').textContent='ONLINE';$('#metricHealthFoot').textContent=data.maigret_available?'Maigret + API':'Maigret install required';if(title)title.innerHTML='<i></i> Backend connected';const led=$('.status-led');if(led)led.classList.add('connected');}catch(error){$('#apiState').textContent='Backend unavailable';$('#apiMeta').textContent='Start the Python server';$('#metricHealth').textContent='OFFLINE';$('#metricHealthFoot').textContent='See README';if(title)title.innerHTML='<i></i> Backend unavailable';const led=$('.status-led');if(led)led.classList.remove('connected');} }
  $('#refreshHealth')?.addEventListener('click',()=>{healthCheck();toast('Backend durumu kontrol ediliyor.');});

  // Sidebar, page navigation, mobile dock, command palette.
  const scrim=document.createElement('div');scrim.id='menuScrim';scrim.className='menu-scrim';document.body.append(scrim);scrim.addEventListener('click',closeSidebar);
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();navigate(nav.dataset.view);return;}const go=e.target.closest('[data-goto]');if(go){navigate(go.dataset.goto);return;}const example=e.target.closest('[data-example]');if(example){$('#universalTarget').value=example.dataset.example;$('#universalForm').requestSubmit();}});
  $('#menuToggle')?.addEventListener('click',()=>$('#sidebar').classList.contains('mobile-open')?closeSidebar():openSidebar());
  function openCommand(){const o=$('#commandOverlay');o.classList.add('open');o.setAttribute('aria-hidden','false');$('#commandInput').value='';filterCommands('');setTimeout(()=>$('#commandInput').focus(),80);}
  function closeCommand(){const o=$('#commandOverlay');o.classList.remove('open');o.setAttribute('aria-hidden','true');}
  function filterCommands(query){const q=query.toLowerCase().trim();$$('#commandList button').forEach((b,i)=>{const show=!q||b.textContent.toLowerCase().includes(q)||b.dataset.cmdView===q;b.classList.toggle('hidden-command',!show);b.classList.remove('selected');if(show&&commandActive===0)commandActive=i;});const visible=$$('#commandList button:not(.hidden-command)');if(visible.length){commandActive=Math.min(commandActive,visible.length-1);visible.forEach((b,i)=>b.classList.toggle('selected',i===commandActive));}}
  $('#openCommand')?.addEventListener('click',openCommand);
  $('#commandOverlay')?.addEventListener('click',e=>{if(e.target.id==='commandOverlay')closeCommand();const button=e.target.closest('[data-cmd-view]');if(button){closeCommand();navigate(button.dataset.cmdView);}});
  $('#commandInput')?.addEventListener('input',e=>{commandActive=0;filterCommands(e.target.value);});
  $('#commandInput')?.addEventListener('keydown',e=>{const visible=$$('#commandList button:not(.hidden-command)');if(e.key==='ArrowDown'){e.preventDefault();commandActive=(commandActive+1)%Math.max(1,visible.length);filterCommands(e.target.value);}else if(e.key==='ArrowUp'){e.preventDefault();commandActive=(commandActive-1+Math.max(1,visible.length))%Math.max(1,visible.length);filterCommands(e.target.value);}else if(e.key==='Escape')closeCommand();else if(e.key==='Enter'){e.preventDefault();const value=e.target.value.trim();if(value){closeCommand();navigate('investigate');$('#universalTarget').value=value;$('#universalForm').requestSubmit();}else if(visible[commandActive]){navigate(visible[commandActive].dataset.cmdView);closeCommand();}}});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();}if((e.metaKey||e.ctrlKey)&&/^[1-9]$/.test(e.key)){const idx=Number(e.key)-1;const keys=Object.keys(views);if(keys[idx]){e.preventDefault();navigate(keys[idx]);}}if(e.key==='Escape'){closeCommand();closeSidebar();}});
  $('#openSettings')?.addEventListener('click',()=>openSync());

  // Main multi-source lookup. Domain queries bundle DNS, RDAP, IP attribution, CT and urlscan.
  $('#lookupTabs').addEventListener('click',e=>{const button=e.target.closest('[data-kind]');if(!button)return;lookupKind=button.dataset.kind;$$('#lookupTabs [data-kind]').forEach(x=>x.classList.toggle('active',x===button));const meta={domain:['Domain adı (example.com)','◌','example.com','example.com','example.com','Try a target:'],ip:['Public IPv4 / IPv6','⌁','8.8.8.8','8.8.8.8','8.8.8.8','Try a target:'],username:['Platformlarda kullanıcı adı','◎','username','octocat','username','Try a target:'],telegram:['Public Telegram username / channel','➤','public_channel','telegram','public_channel','Try a target:'],github:['GitHub username','⌘','octocat','octocat','octocat','Try a target:']}[lookupKind];$('#targetHelp').textContent=meta[0];$('#universalGlyph').textContent=meta[1];$('#universalTarget').placeholder=meta[2];const examples=$('#targetExamples');examples.innerHTML=`<span>Try a target:</span>`+(lookupKind==='domain'?['example.com','github.com']:lookupKind==='ip'?['8.8.8.8','1.1.1.1']:lookupKind==='username'?['octocat','torvalds']:lookupKind==='telegram'?['telegram','durov']:['octocat','torvalds']).map(x=>`<button type="button" data-example="${x}">${x}</button>`).join('');});
  $('#clearUniversal').addEventListener('click',()=>{$('#universalTarget').value='';$('#universalTarget').focus();});
  $('#universalForm').addEventListener('submit',async e=>{e.preventDefault();const target=$('#universalTarget').value.trim();$('#universalResultTitle').textContent=`Research — ${target}`;await runForm(e.currentTarget,$('#universalResults'),'Universal lookup',async()=>{
    if(lookupKind==='domain')return runBundle(target,[{label:'Domain / RDAP',path:`/api/rdap?target=${encodeURIComponent(target)}`,source:'https://rdap.org/'},{label:'DNS records',path:`/api/dns?domain=${encodeURIComponent(target)}`,source:'https://developers.cloudflare.com/1.1.1.1/encryption/dns-over-https/'},{label:'IP / network attribution',path:`/api/ip?target=${encodeURIComponent(target)}`,source:'https://ipwho.is/'},{label:'Certificate transparency',path:`/api/certificates?domain=${encodeURIComponent(target)}`,source:'https://crt.sh/'},{label:'Public URL scan archive',path:`/api/urlscan?domain=${encodeURIComponent(target)}`,source:'https://urlscan.io/'}]);
    if(lookupKind==='ip')return runBundle(target,[{label:'IP / network attribution',path:`/api/ip?target=${encodeURIComponent(target)}`,source:'https://ipwho.is/'},{label:'RDAP registry record',path:`/api/rdap?target=${encodeURIComponent(target)}`,source:'https://rdap.org/'}]);
    if(lookupKind==='username')return api(`/api/username?username=${encodeURIComponent(target)}&depth=${scanDepth}`,{timeout:240000});
    if(lookupKind==='telegram')return api(`/api/telegram?username=${encodeURIComponent(target)}`,{timeout:50000});
    return api(`/api/github?username=${encodeURIComponent(target)}`,{timeout:30000});
  },{target,loading:'Multi-source investigation',detail:'Gerçek public kaynaklar sorgulanıyor; kaynaklar bağımsız sonuç verebilir.',button:'Querying',status:'#universalStatus',render:payload=>payload.bundle?renderBundle(payload):renderBundleChild(payload),summary:`${lookupKind} · ${target}`,source:lookupKind==='telegram'?'https://t.me/':lookupKind==='github'?'https://docs.github.com/en/rest':''});});

  // Maigret username engine.
  $('#scanDepth').addEventListener('click',e=>{const b=e.target.closest('[data-depth]');if(!b)return;scanDepth=b.dataset.depth;$$('#scanDepth [data-depth]').forEach(x=>x.classList.toggle('active',x===b));});
  $('#usernameForm').addEventListener('submit',async e=>{e.preventDefault();const username=$('#usernameInput').value.trim().replace(/^@/,'');$('#usernameTitle').textContent=`Scan report — @${username}`;await runForm(e.currentTarget,$('#usernameOutput'),'Maigret scan',()=>api(`/api/username?username=${encodeURIComponent(username)}&depth=${scanDepth}`,{timeout:260000}),{target:username,loading:'Maigret live scan',detail:'Seçilen sayıda siteye istek gönderiliyor. Bazı siteler yavaş, engelli veya belirsiz sonuç verebilir.',button:'Scanning',status:'#usernameStatus',render:renderMaigret,summary:`${scanDepth} scan · ${username}`,source:'https://github.com/soxoj/maigret'});});
  $('#telegramForm').addEventListener('submit',async e=>{e.preventDefault();const username=$('#telegramInput').value.trim().replace(/^@/,'');await runForm(e.currentTarget,$('#telegramOutput'),'Telegram Public',()=>api(`/api/telegram?username=${encodeURIComponent(username)}`,{timeout:50000}),{target:username,loading:'Fetching Telegram public preview',detail:'t.me public web sayfası ve izin verilen kanal önizlemesi isteniyor.',button:'Querying',render:renderTelegram,source:`https://t.me/${encodeURIComponent(username)}`});});
  $('#ipForm').addEventListener('submit',async e=>{e.preventDefault();const target=$('#ipInput').value.trim();await runForm(e.currentTarget,$('#ipOutput'),'IP Intelligence',()=>api(`/api/ip?target=${encodeURIComponent(target)}`),{target,loading:'Resolving IP attribution',render:renderIp,source:'https://ipwho.is/'});});
  $('#rdapForm').addEventListener('submit',async e=>{e.preventDefault();const target=$('#rdapInput').value.trim();await runForm(e.currentTarget,$('#rdapOutput'),'Domain / RDAP',()=>api(`/api/rdap?target=${encodeURIComponent(target)}`),{target,loading:'Querying registry RDAP',render:renderRdap,source:'https://rdap.org/'});});
  $('#dnsForm').addEventListener('submit',async e=>{e.preventDefault();const domain=$('#dnsInput').value.trim();await runForm(e.currentTarget,$('#dnsOutput'),'DNS Records',()=>api(`/api/dns?domain=${encodeURIComponent(domain)}`),{target:domain,loading:'Resolving public DNS records',render:renderDns,source:'https://developers.cloudflare.com/1.1.1.1/encryption/dns-over-https/'});});
  $('#certForm').addEventListener('submit',async e=>{e.preventDefault();const domain=$('#certInput').value.trim();await runForm(e.currentTarget,$('#certOutput'),'Certificate Intel',()=>api(`/api/certificates?domain=${encodeURIComponent(domain)}`,{timeout:50000}),{target:domain,loading:'Searching Certificate Transparency logs',render:renderCerts,source:'https://crt.sh/'});});
  $('#urlscanForm').addEventListener('submit',async e=>{e.preventDefault();const domain=$('#urlscanInput').value.trim();await runForm(e.currentTarget,$('#urlscanOutput'),'URL Scan Archive',()=>api(`/api/urlscan?domain=${encodeURIComponent(domain)}&size=30`,{timeout:50000}),{target:domain,loading:'Searching public urlscan archive',render:renderUrlscan,source:'https://urlscan.io/docs/'});});
  $('#githubForm').addEventListener('submit',async e=>{e.preventDefault();const username=$('#githubInput').value.trim().replace(/^@/,'');await runForm(e.currentTarget,$('#githubOutput'),'GitHub Intelligence',()=>api(`/api/github?username=${encodeURIComponent(username)}`,{timeout:30000}),{target:username,loading:'Fetching public GitHub profile',render:renderGitHub,source:'https://docs.github.com/en/rest'});});
  $('#emailForm').addEventListener('submit',async e=>{e.preventDefault();let value=$('#emailInput').value.trim();const domain=value.includes('@')?value.split('@').pop().toLowerCase():value.toLowerCase();await runForm(e.currentTarget,$('#emailOutput'),'Email / MX',()=>api(`/api/dns?domain=${encodeURIComponent(domain)}`),{target:value,loading:'Inspecting public mail DNS records',render:renderEmail,source:'https://developers.cloudflare.com/1.1.1.1/encryption/dns-over-https/'});});
  $('#webSearchForm').addEventListener('submit',async e=>{e.preventDefault();const target=$('#webSearchInput').value.trim();await runForm(e.currentTarget,$('#webSearchOutput'),'Web Research',()=>api(`/api/search-links?query=${encodeURIComponent(target)}`),{target,loading:'Building public search set',render:renderSearchLinks,source:'https://duckduckgo.com/'});});

  // Saved record interactions, JSON export/import, and delete propagation tombstones.
  document.addEventListener('click',e=>{const open=e.target.closest('[data-history-open]');if(open){const rec=history.find(x=>String(x.id)===open.dataset.historyOpen);if(rec)showSavedRecord(rec);return;}const del=e.target.closest('[data-history-delete]');if(del){addTombstone(del.dataset.historyDelete);history=history.filter(x=>String(x.id)!==del.dataset.historyDelete);persistHistory();toast('Kayıt silindi.');}});
  function showSavedRecord(rec){navigate('investigate');$('#universalTarget').value=rec.target;$('#universalResultTitle').textContent=`Saved report — ${rec.target}`;$('#universalStatus').textContent='LOCAL RECORD';$('#universalStatus').className='result-state state-idle';const data=rec.result||{};let body;if(data.bundle)body=renderBundle(data);else if(data.profile&&data.recent_repositories)body=renderGitHub(data);else if(data.public_posts||data.page_kind)body=renderTelegram(data);else if(data.summary&&data.found)body=renderMaigret(data);else if(data.records&&data.record_types)body=rec.type==='Email / MX'?renderEmail(data):renderDns(data);else if(data.certificates)body=renderCerts(data);else if(data.ip&&data.isp!==undefined)body=renderIp(data);else if(data.rdap)body=renderRdap(data);else if(data.links)body=renderSearchLinks(data);else body=renderGeneric(data);$('#universalResults').innerHTML=`<div class="saved-banner">LOCAL SAVED REPORT · ${formatDate(rec.time)} · ${escapeHTML(rec.type)}</div>${body}`;}
  function downloadFile(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('#exportHistory').addEventListener('click',()=>{downloadFile('nex-osint-report.json',JSON.stringify({app:'NEX OSINT Pro',version:'1.1.0',exported_at:new Date().toISOString(),history},null,2));toast('JSON raporu indirildi.');});
  $('#importHistory').addEventListener('click',()=>$('#historyFile').click());
  $('#historyFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const payload=JSON.parse(await file.text());const incoming=Array.isArray(payload)?payload:payload.history;if(!Array.isArray(incoming))throw new Error('JSON içinde history dizisi bulunamadı');const existing=new Set(history.map(x=>String(x.id))),dead=new Set(syncTombstones);const merged=[...incoming.filter(x=>x&&x.target&&x.id!=null&&!existing.has(String(x.id))&&!dead.has(String(x.id))),...history].slice(0,HISTORY_LIMIT);history=merged;persistHistory();toast(`${incoming.length} kayıt içe aktarıldı.`);}catch(err){toast(`JSON içe aktarılamadı: ${apiError(err)}`,'error');}finally{e.target.value='';}});
  $('#clearHistory').addEventListener('click',()=>{if(confirm('Bu çalışma alanındaki geçmiş bağlı cihazlardan da silinsin mi?')){history.forEach(rec=>addTombstone(rec.id));history=[];persistHistory();toast('Geçmiş silindi; bağlı cihazlara aktarılacak.');}});

  // Optional end-to-end encrypted cross-device sync. AES key remains inside the private pairing code.
  function readSyncConfig(){try{const value=JSON.parse(localStorage.getItem(SYNC_CONFIG_KEY)||'null');return value&&value.id&&value.key&&value.proof?value:null;}catch{return null;}}
  function readSyncTombstones(){try{const value=JSON.parse(localStorage.getItem(SYNC_TOMBSTONES_KEY)||'[]');return Array.isArray(value)?value.map(String).slice(-5000):[];}catch{return [];}}
  function persistTombstones(){try{localStorage.setItem(SYNC_TOMBSTONES_KEY,JSON.stringify(syncTombstones.slice(-5000)));}catch{}}
  function addTombstone(id){if(id==null)return;const value=String(id);if(!syncTombstones.includes(value))syncTombstones.push(value);syncTombstones=syncTombstones.slice(-5000);persistTombstones();}
  function randomBytes(length){const bytes=new Uint8Array(length);crypto.getRandomValues(bytes);return bytes;}
  function toBase64Url(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
  function fromBase64Url(value){const normalized=String(value).replace(/-/g,'+').replace(/_/g,'/');const binary=atob(normalized+'='.repeat((4-normalized.length%4)%4));return Uint8Array.from(binary,ch=>ch.charCodeAt(0));}
  function makeSyncCode(){if(!crypto?.subtle||!crypto?.getRandomValues)throw new Error('Şifreleme için HTTPS veya localhost gerekir.');const id=crypto.randomUUID();const key=toBase64Url(randomBytes(32)),proof=toBase64Url(randomBytes(32));return{id,key,proof,code:`NEXSYNC1.${id}.${key}.${proof}`,createdAt:new Date().toISOString()};}
  function parseSyncCode(input){const code=String(input||'').trim().replace(/\s+/g,'');const match=code.match(/^NEXSYNC1\.([0-9a-f-]{36})\.([A-Za-z0-9_-]{43})\.([A-Za-z0-9_-]{43})$/i);if(!match)throw new Error('Pairing code biçimi geçersiz. Diğer cihazdan kodun tamamını kopyala.');const id=match[1].toLowerCase();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(id))throw new Error('Pairing code içindeki workspace ID geçersiz.');if(fromBase64Url(match[2]).length!==32||fromBase64Url(match[3]).length!==32)throw new Error('Pairing code anahtarı bozuk.');return{id,key:match[2],proof:match[3],code,createdAt:new Date().toISOString()};}
  function showSyncState(title,detail,state='idle'){const status=$('#syncModalStatus'),desc=$('#syncModalDetail'),led=$('#syncModalLed');if(status)status.textContent=title;if(desc)desc.textContent=detail;if(led)led.className='sync-state-led'+(state==='live'?' live':state==='error'?' error':'');const top=$('#openSyncTop');if(top)top.classList.toggle('connected',!!syncConfig&&state!=='error');const dot=$('#syncTopDot');if(dot)dot.style.background=syncConfig?(state==='error'?'#d99b9b':'#b7e2b0'):'#777';}
  function renderSyncState(){if(!syncConfig){showSyncState('Local-only mode','Bu cihazda kayıtlar yerel. PC ve telefon eşitlemesi için bir pairing code oluştur.','idle');return;}const area=$('#syncCodeInput');if(area&&!area.value)area.value=syncConfig.code||'';showSyncState('Encrypted workspace connected',`Workspace ${syncConfig.id.slice(0,8)}… · sorgu ve kayıt değişiklikleri otomatik eşitlenir.`,'live');}
  function openSync(){renderSyncState();$('#syncOverlay').classList.add('open');$('#syncOverlay').setAttribute('aria-hidden','false');}
  function closeSync(){const overlay=$('#syncOverlay');overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');}
  async function importAesKey(){return crypto.subtle.importKey('raw',fromBase64Url(syncConfig.key),{name:'AES-GCM'},false,['encrypt','decrypt']);}
  async function packPayload(payload){const raw=new TextEncoder().encode(JSON.stringify(payload));if('CompressionStream'in window){try{const packed=await new Response(new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();if(packed.byteLength<raw.byteLength){const out=new Uint8Array(packed.byteLength+1);out[0]=1;out.set(new Uint8Array(packed),1);return out;}}catch{}}const out=new Uint8Array(raw.byteLength+1);out[0]=0;out.set(raw,1);return out;}
  async function encodeSyncEnvelope(payload){const iv=randomBytes(12),key=await importAesKey(),bytes=await packPayload(payload);const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);return{v:1,nonce:toBase64Url(iv),ciphertext:toBase64Url(new Uint8Array(encrypted))};}
  async function decodeSyncEnvelope(envelope){const key=await importAesKey();const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromBase64Url(envelope.nonce)},key,fromBase64Url(envelope.ciphertext));const bytes=new Uint8Array(plain);if(!bytes.length)throw new Error('Şifreli sync verisi boş.');let data=bytes.subarray(1);if(bytes[0]===1){if(!('DecompressionStream'in window))throw new Error('Bu tarayıcı gzip sync verisini açamıyor; güncel Chrome, Edge veya Safari kullan.');data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());}const payload=JSON.parse(new TextDecoder().decode(data));if(payload?.v!==1||!Array.isArray(payload.history)||!Array.isArray(payload.tombstones))throw new Error('Sync verisinin yapısı geçersiz.');return payload;}
  function makeSyncPayload(){return{v:1,history:history.slice(0,HISTORY_LIMIT),tombstones:syncTombstones.slice(-5000)};}
  function mergeSyncPayload(remote){const dead=new Set([...syncTombstones,...remote.tombstones.map(String)]);syncTombstones=[...dead].slice(-5000);persistTombstones();const byId=new Map();for(const rec of [...remote.history,...history]){if(!rec||rec.id==null||!rec.target||dead.has(String(rec.id)))continue;const key=String(rec.id),old=byId.get(key);if(!old||new Date(rec.time||0).getTime()>=new Date(old.time||0).getTime())byId.set(key,rec);}history=[...byId.values()].sort((a,b)=>new Date(b.time||0).getTime()-new Date(a.time||0).getTime()).slice(0,HISTORY_LIMIT);persistHistory({skipSync:true});}
  async function syncNow(manual=false,allowCreate=false){if(!syncConfig)return false;if(syncInFlight){syncAgain=true;return false;}syncInFlight=true;showSyncState('Syncing encrypted history…','Şifreli çalışma alanı okunuyor ve birleştiriliyor.','idle');try{let remote=null;try{remote=await api(`/api/sync/${encodeURIComponent(syncConfig.id)}`,{timeout:25000,headers:{'X-Sync-Proof':syncConfig.proof}});}catch(error){if(error.status!==404)throw error;if(!allowCreate)throw new Error('Bu pairing code için sunucu kaydı bulunamadı. İlk cihazda code oluşturulduğundan emin ol.');}if(remote)mergeSyncPayload(await decodeSyncEnvelope(remote.envelope));const envelope=await encodeSyncEnvelope(makeSyncPayload());await api(`/api/sync/${encodeURIComponent(syncConfig.id)}`,{timeout:30000,method:'PUT',headers:{'Content-Type':'application/json','X-Sync-Proof':syncConfig.proof},body:JSON.stringify(envelope)});showSyncState('Encrypted sync is up to date',`Son eşitleme: ${new Date().toLocaleTimeString()} · ${history.length} yerel kayıt.`,'live');if(manual)toast('Şifreli geçmiş eşitlendi.');return true;}catch(error){showSyncState('Sync could not finish',apiError(error),'error');if(manual)toast(`Sync başarısız: ${apiError(error)}`,'error');return false;}finally{syncInFlight=false;if(syncAgain){syncAgain=false;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(false,false),700);}}}
  function scheduleSync(){persistTombstones();if(!syncConfig)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(false,false),1800);}
  $('#openSyncTop')?.addEventListener('click',openSync);$('#openSyncHistory')?.addEventListener('click',openSync);$('#closeSync')?.addEventListener('click',closeSync);$('#syncOverlay')?.addEventListener('click',e=>{if(e.target.id==='syncOverlay')closeSync();});
  $('#createSyncCode')?.addEventListener('click',async()=>{try{const code=makeSyncCode();syncConfig=code;localStorage.setItem(SYNC_CONFIG_KEY,JSON.stringify(code));$('#syncCodeInput').value=code.code;showSyncState('Creating encrypted workspace…','Sunucu kaydı hazırlanıyor. Pairing code ikinci cihazla güvenli paylaşılır.','idle');await syncNow(true,true);}catch(error){showSyncState('Pairing code could not be created',apiError(error),'error');toast(apiError(error),'error');}});
  $('#connectSyncCode')?.addEventListener('click',async()=>{try{const parsed=parseSyncCode($('#syncCodeInput').value);syncConfig=parsed;localStorage.setItem(SYNC_CONFIG_KEY,JSON.stringify(parsed));await syncNow(true,false);}catch(error){showSyncState('Could not connect',apiError(error),'error');toast(apiError(error),'error');}});
  $('#copySyncCode')?.addEventListener('click',async()=>{const value=$('#syncCodeInput').value.trim();if(!value){toast('Önce pairing code oluştur veya yapıştır.','error');return;}try{await navigator.clipboard.writeText(value);toast('Pairing code panoya kopyalandı; özel tut.');}catch{$('#syncCodeInput').focus();$('#syncCodeInput').select();toast('Kod seçildi. Tarayıcı kopyalama izni vermedi; manuel kopyala.');}});
  $('#disconnectSync')?.addEventListener('click',()=>{if(!syncConfig)return;if(!confirm('Bu cihazdaki sync bağlantısı kesilsin mi? Sunucudaki şifreli kopya ve diğer cihazlar silinmez.'))return;syncConfig=null;localStorage.removeItem(SYNC_CONFIG_KEY);clearTimeout(syncTimer);$('#syncCodeInput').value='';showSyncState('Local-only mode','Bu cihaz artık otomatik eşitlenmiyor. Sunucudaki şifreli kopya silinmedi.','idle');toast('Bu cihazın eşitlemesi kapatıldı.');});
  $('#syncNowButton')?.addEventListener('click',()=>syncNow(true,false));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#syncOverlay')?.classList.contains('open'))closeSync();});

  window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast(apiError(event.reason),'error');});
  renderMetrics();renderRecent();renderHistory();healthCheck();renderSyncState();if(syncConfig)setTimeout(()=>syncNow(false,false),700);
})();
